INSERT  INTO `item_template_locale`(`ID`,`locale`,`Name`,`Description`,`VerifiedBuild`) VALUES
(3930,'zhCN','玛雷的钥匙','',15050);
INSERT INTO `npc_text_locale`(`ID`,`Locale`,`Text0_0`,`Text0_1`,`Text1_0`,`Text1_1`,`Text2_0`,`Text2_1`,`Text3_0`,`Text3_1`,`Text4_0`,`Text4_1`,`Text5_0`,`Text5_1`,`Text6_0`,`Text6_1`,`Text7_0`,`Text7_1`) VALUES
(1,'zhCN','嘿, $N.需要我帮忙吗?','嗨, $n.','很高兴见到你 $N','嘿, $N.需要我帮忙吗?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(2,'zhCN','嗨！亲爱的朋友！ $N 要我帮忙吗？','嗨！亲爱的朋友！ $N 要我帮忙吗？','嘿, $N.需要我帮忙吗?','嗨！亲爱的朋友！ $N 要我帮忙吗？',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(3,'zhCN','你好，居民。如果你没什么事要问我，那就请你走吧。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(4,'zhCN','我活着就是为了为国王服务。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(5,'zhCN','快点离开，居民。没有什么好看的。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(18,'zhCN','待在我身边，$n。我们或许会需要彼此的协助。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(24,'zhCN','啊，$n!有只小鸟通知了我你的到来。$B$B这就是艾维娜传达讯息的方式。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(34,'zhCN','Which profession?','哪一项专业技能?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(42,'zhCN','死亡之翼又回来了。他夺下了格瑞姆巴托和大半块的高地，而且我感觉根本无力阻止他。$B$B但不久之後我们龙后就会抵达，然後我们将一起协力将这位堕落的大地守护者埋回大地。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(48,'zhCN','How may I help you?','我可以帮你吗?','How may I help you?','How may I help you?','How may I help you?','How may I help you?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(68,'zhCN','欢迎你, $n.','你好，$n。','很高兴见到你 $N','见到你很高兴 $N',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(82,'zhCN','效忠龙喉氏族，你会获得可观的奖赏，$c。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(107,'zhCN',NULL,'嗯?你要什么?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(134,'zhCN','部落的作战部队需要你!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(141,'zhCN',NULL,'领导的重担对我而言仍然相当陌生。我应该早料到纳克拉尔的反叛是迟早会发生的才对，结果我却坐视不理，到如今才在收拾他引起的烂摊子。$B$B我不晓得卡尔洛斯·地狱吼是怎样办到的，他必定拥有坚强的意志和力量才能让如此分歧的部落团结在一起...我很想要多了解他一些。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(153,'zhCN','嗨呀，$g勇士:女士;最近如何?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(158,'zhCN',NULL,'欢迎，$c。$B$B海加尔正在燃烧，我一生都在保护的世界也面临着毁坏。$B$B你有听过泰洛斯·黑角这个名字吗?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(166,'zhCN','我们为战争而来。$B$B他们满足了我们。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(185,'zhCN','想要的话，你可以在这里休息。如今大地神殿是在我们的照管之下。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(194,'zhCN','欢迎来到我的旅店，疲累的旅人。我能为你做点什么吗?','欢迎来到我的旅店，疲累的旅人。我能为你做点什么吗?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(197,'zhCN','嘿，你好，市民。你看起来很强壮。我们这里的防卫有点弱，我想请你帮帮忙……',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(215,'zhCN',NULL,'原本我们还一直期待，总有办法能够挽救大地看守者和他的後裔。但有时候，我们必须要有足够的智慧认清事实，这群恶龙对世界所造成的伤害与毁灭确实早已罪不可赦。$B$B有时候，我们必得现身干预。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(225,'zhCN','兽人，在我有生之年我还没看过这种...',NULL,'We are poorly equipped to do battle here.$b$bPreparations must be made...',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(246,'zhCN','让我们离开这里，去把那些岩石穴居怪打回土里，$r!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(247,'zhCN','我需要你到前线去，$n。$B$B你可以帮我们扭转战局，我们会彻底击垮岩石穴居怪。$B$B我们一定要救出矿被国王!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(248,'zhCN','<克雷闷哼狞笑。>$B$B该死的小鬼。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(328,'zhCN','欢迎你, $n.','你好，$n。','你好$N','你好 $N。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(384,'zhCN','欢迎你, $n.','你好，$n。','你好 $N。','很高兴见到你 $N',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(401,'zhCN','野锤矮人也许可能有快速的马, 但那些艾瑞峰高峰格瑞夫恩站立的地方不是真正的炎热吗? 我认为不是!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(447,'zhCN','试炼谷是任何一个加入部落的成员都应该接受测试的地方。那里炎热的太阳考验这你的耐性！',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(518,'zhCN','做自己的老板感觉真不错!$B$B可以给我些铜币让我买个三明治吗?我饿坏了。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(519,'zhCN','雷德沃克斯主管曾让我负责新型伐木机的研发计画，但我上个月自己单飞了。现在，所有的供应商都把我列入了黑名单，更糟的是，我的研发计划根本都还没开始。我需要你的帮助，$n!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(520,'zhCN','我想我可以用这个方法开始进行我的研发计划，呃...就是跟风险投资公司「借」一些他们的科技。看，他们的新型伐木机是最棒的，不管是可拆换的机械臂到控制把手都是!$B$B我的生意夥伴维兹克兰克到西边的淤泥沼泽偷...呃...是做些实地勘查，但到现在还没回来。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(521,'zhCN','你杀了鬼嚎。你这个傻瓜!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(522,'zhCN','年轻的$c，靠近一点。我年轻的时候耳朵可好使了，但现在你必须大声说话我才能听到。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(523,'zhCN','我在这片平原上生活了很多很多年，我捕猎过许多凶猛的野兽，从来没有失败过...直到我遇见了鬼嚎。$B$B很久以前，这只巨狼曾经是牛头人的盟友，还和燃烧军团英勇作战。不过後来它被一个恶魔所伤，身上的伤口一直没有治癒。最後...这道伤口把它逼疯了。$B$B现在它总是痛苦地在平原上游荡，寻找终止它的痛苦的方法。我很惭愧，因为我无力把他杀掉...',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
